#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "durbin.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      r[i] = (n+1-i);
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations compared to the original version:
   - Removed the temporary array z[N] and perform the y-update in-place
     using symmetric pairwise updates. This cuts the write traffic to
     y[] in half and removes one full pass over y[] per outer iteration.
   - Rewrote the inner dot-product loop to use pointer increments instead
     of repeatedly computing r[k-i-1]. This keeps both r[] and y[] accesses
     stride-1 (one forward, one backward) and simplifies the address
     arithmetic, which helps the compiler generate better code.
   - Introduced local pointer aliases r_local/y_local to make it explicit
     that we always work with the same base addresses; this can also help
     the optimizer while keeping the original interface intact.

   All arithmetic operations for each element are mathematically identical
   to the original formulation; only the order in which independent
   elements are updated is changed, which does not affect the result.
*/
static
void kernel_durbin[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Local aliases improve readability and can help compiler analysis.
     Types and indexing semantics remain identical to the originals. */
  DATA_TYPE *y_local       = y;
  const DATA_TYPE *r_local = r;

  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

#pragma scop
  /* Initial conditions. */
  y_local[0] = -r_local[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r_local[0];

  for (k = 1; k < _PB_N; k++)
  {
    /* Recurrence for beta. Kept in multiplicative form to match
       original arithmetic as closely as possible. */
    beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;

    /* Dot product:
       sum = sum_{i=0}^{k-1} r[k-1-i] * y[i]

       Using two walking pointers keeps both accesses as unit-stride
       (r backwards, y forwards) and avoids recomputing k-i-1. */
    sum = SCALAR_VAL(0.0);

    const DATA_TYPE *r_ptr = r_local + (k - 1); /* starts at r[k-1] */
    const DATA_TYPE *y_ptr = y_local;           /* starts at y[0]   */

    for (i = 0; i < k; i++)
    {
      sum += (*r_ptr) * (*y_ptr);
      --r_ptr;   /* move backward through r[] */
      ++y_ptr;   /* move forward through y[]  */
    }

    /* Update reflection coefficient. */
    alpha = -(r_local[k] + sum) / beta;

    /* Original code:
       for (i = 0; i < k; i++)
         z[i] = y[i] + alpha * y[k-i-1];
       for (i = 0; i < k; i++)
         y[i] = z[i];

       This computes:
         new_y[i] = old_y[i] + alpha * old_y[k-1-i]

       We can perform this update in-place without the temporary z[]
       by exploiting the symmetry between index pairs (i, j = k-1-i).

       For each pair (i, j) with i < j:
         new_y[i] = old_y[i] + alpha * old_y[j]
         new_y[j] = old_y[j] + alpha * old_y[i]

       We read old_y[i] and old_y[j] into temporaries before writing
       either location, so we never read an element after it has been
       updated. For odd k there is a single middle element i == j,
       where:
         new_y[mid] = old_y[mid] + alpha * old_y[mid]
                    = (1 + alpha) * old_y[mid]

       This is mathematically identical to the original two-pass
       formulation but halves the number of writes and eliminates
       the extra array. */

    int half = k >> 1; /* floor(k/2) */

    /* Update symmetric pairs (i, k-1-i). */
    for (i = 0; i < half; i++)
    {
      int j = k - 1 - i;
      DATA_TYPE yi = y_local[i];
      DATA_TYPE yj = y_local[j];

      y_local[i] = yi + alpha * yj;
      y_local[j] = yj + alpha * yi;
    }

    /* If k is odd, handle the middle element where i == k-1-i. */
    if (k & 1)
    {
      int mid = half;
      DATA_TYPE ym = y_local[mid];
      y_local[mid] = ym + alpha * ym;
    }

    /* Set the last element for this iteration. */
    y_local[k] = alpha;
  }
#pragma endscop

  (void)n; /* n is unused but part of the original interface. */
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(r));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_durbin (n,
		 POLYBENCH_ARRAY(r),
		 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(r);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
