  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_durbin[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Create local restrict-qualified aliases.  In this benchmark, r and y
     refer to distinct arrays, so using __restrict here is valid and allows
     the compiler to generate better optimized code. */
  DATA_TYPE * __restrict r_ = r;
  DATA_TYPE * __restrict y_ = y;

  const DATA_TYPE one = SCALAR_VAL(1.0);

  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

#pragma scop
  /* Initial conditions. */
  y_[0] = -r_[0];
  beta  = one;
  alpha = -r_[0];

  for (k = 1; k < _PB_N; k++) {
    /* Update beta using the previous alpha. */
    beta = (one - alpha * alpha) * beta;

    /* Compute:
         sum = Σ_{i=0..k-1} r[k-1-i] * y[i]
       Expressed with simple indexing to keep the loop analyzable and
       vectorization-friendly. */
    sum = SCALAR_VAL(0.0);
    for (i = 0; i < k; i++) {
      sum += r_[k - 1 - i] * y_[i];
    }

    /* New reflection coefficient. */
    alpha = -(r_[k] + sum) / beta;

    /* Original code:
         for (i = 0; i < k; i++)
           z[i] = y[i] + alpha * y[k-i-1];
         for (i = 0; i < k; i++)
           y[i] = z[i];

       This can be done in-place without the temporary z[] by exploiting
       symmetry:
         For each pair (i, j = k-1-i) we read the *old* y[i] and y[j],
         compute both new values, then write them back.  The middle element
         when k is odd is treated separately.  This transformation is
         algebraically identical (element-wise) but reduces memory traffic
         and improves cache behavior. */
    {
      const DATA_TYPE alpha_local = alpha;
      const int half   = k >> 1;   /* floor(k/2)  */
      const int is_odd = k & 1;    /* k % 2 != 0  */

      /* Update symmetric pairs (i, j = k-1-i). Each iteration reads the
         original y[i] and y[j] and updates both, so no extra buffer is
         needed and there are no loop-carried dependencies. */
      for (i = 0; i < half; i++) {
        const int j = k - 1 - i;
        const DATA_TYPE y_i = y_[i];
        const DATA_TYPE y_j = y_[j];

        y_[i] = y_i + alpha_local * y_j;
        y_[j] = y_j + alpha_local * y_i;
      }

      /* Handle the middle element when k is odd: it maps to itself in the
         original transformation:
           z[mid] = y[mid] + alpha * y[mid].
         We compute that expression directly to preserve the original
         floating-point evaluation structure. */
      if (is_odd) {
        const int mid = half;
        const DATA_TYPE y_mid = y_[mid];
        y_[mid] = y_mid + alpha_local * y_mid;
      }
    }

    /* Last element in this iteration. */
    y_[k] = alpha;
  }
#pragma endscop

}


