/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 * - Removed the temporary array `z[]` by performing an in-place,
 *   symmetric update of `y`. This reduces memory traffic and improves
 *   cache behavior while preserving the exact mathematical result.
 * - Reordered the inner summation loop to access `r` and `y` in a
 *   more cache-friendly manner (both mostly linear in memory).
 * - Introduced local `__restrict` pointer aliases to help the compiler
 *   with alias analysis and vectorization.
 * - Added light-weight loop hints (`#pragma GCC ivdep`) for potential
 *   auto-vectorization where safe.
 */
static
void kernel_durbin[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

  /* Local restrict-qualified aliases to help the optimizer.
     The PolyBench harness allocates `r` and `y` as distinct arrays,
     so this assumption is valid. */
  DATA_TYPE *__restrict r_ptr = r;
  DATA_TYPE *__restrict y_ptr = y;

#pragma scop
  y_ptr[0] = -r_ptr[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r_ptr[0];

  const int n_pb = _PB_N;

  for (k = 1; k < n_pb; k++) {
    /* Same recurrence as original: beta = (1 - alpha^2) * beta. */
    beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;

    /* Compute sum = sum_{i=0}^{k-1} r[k-1-i] * y[i]
       using forward access for y and backward for r. */
    sum = SCALAR_VAL(0.0);
    DATA_TYPE *rk = r_ptr + (k - 1);
    DATA_TYPE *yi = y_ptr;
#pragma GCC ivdep
    for (i = 0; i < k; i++) {
      sum += (*rk--) * (*yi++);
    }

    alpha = -(r_ptr[k] + sum) / beta;

    /* In-place symmetric update of y:
       Original:
         for (i = 0; i < k; i++)
           z[i] = y[i] + alpha * y[k-1-i];
         for (i = 0; i < k; i++)
           y[i] = z[i];
       This defines:
         y_new[i] = y_old[i] + alpha * y_old[k-1-i]  for 0 <= i < k.
       We can update pairs (i, j = k-1-i) simultaneously without a
       temporary array, as long as we read both old values before
       writing either one. For odd k, the middle element (i == j)
       is handled separately. */
    int i_left  = 0;
    int i_right = k - 1;

#pragma GCC ivdep
    while (i_left < i_right) {
      DATA_TYPE y_left  = y_ptr[i_left];
      DATA_TYPE y_right = y_ptr[i_right];

      y_ptr[i_left]  = y_left  + alpha * y_right;
      y_ptr[i_right] = y_right + alpha * y_left;

      ++i_left;
      --i_right;
    }

    /* Handle central element when k is odd (i_left == i_right).
       In that case:
         y_new[i] = y_old[i] + alpha * y_old[i]
                  = (1 + alpha) * y_old[i]. */
    if (i_left == i_right) {
      DATA_TYPE y_c = y_ptr[i_left];
      y_ptr[i_left] = y_c + alpha * y_c;
    }

    y_ptr[k] = alpha;
  }
#pragma endscop

}


